#include <cuda_runtime.h>
#include <vector>
#include <fstream>
#include <cstdint>
#include <cstring>
#include "../crs-cuda/utils.h"
#include "../crs-cuda/GCRSMatrix.h"
#include "../crs-cuda/kernels.cu"
static_assert(sizeof(long)==8,"Nativewordwidth");
void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}
std::vector<uint64_t>load(const char*p){std::ifstream f(p,std::ios::binary|std::ios::ate);size_t n=f.tellg();f.seekg(0);std::vector<uint64_t>v(n/8);f.read((char*)v.data(),n);return v;}
const uint64_t SENT=0xdecafbad12345678ULL;const uint32_t BSENT=0xa5a5a5a5;
struct S{int k,m,w,size,tasks,mode,blocks;uint64_t*a,*b;uint32_t*bm;std::vector<uint64_t>ah;std::vector<uint32_t>bh;};
int main(){auto fixture=load(CRS_FIXTURE),oracle=load(CRS_ORACLE);std::vector<S>states;size_t off=0;while(off<fixture.size()){S s;s.k=fixture[off];s.m=fixture[off+1];s.w=fixture[off+2];s.size=fixture[off+3];s.tasks=fixture[off+4];s.mode=fixture[off+5];s.bh.push_back(BSENT);for(int i=0;i<s.k*s.w;i++)s.bh.push_back(uint32_t(fixture[off+6+i]));s.bh.push_back(BSENT);s.ah.push_back(SENT);s.ah.insert(s.ah.end(),fixture.begin()+off+6+s.k*s.w,fixture.begin()+off+6+s.k*s.w+s.k*s.size*s.tasks);s.ah.push_back(SENT);off+=6+s.k*s.w+s.k*s.size*s.tasks;
auto*mat=gcrs_create_bitmatrix(s.k,s.m,s.w);auto*col=gcrs_create_column_coding_bitmatrix(s.k,s.m,s.w,mat);for(int i=0;i<s.k*s.w;i++)if(col[i]!=s.bh[i+1])return 6;free(mat);free(col);
ck(cudaMalloc(&s.a,s.ah.size()*8));ck(cudaMalloc(&s.b,(s.m*s.size*s.tasks+2)*8));ck(cudaMalloc(&s.bm,s.bh.size()*4));ck(cudaMemcpy(s.a,s.ah.data(),s.ah.size()*8,cudaMemcpyHostToDevice));ck(cudaMemcpy(s.bm,s.bh.data(),s.bh.size()*4,cudaMemcpyHostToDevice));s.blocks=(s.size+4*(32/s.w)*s.w-1)/(4*(32/s.w)*s.w);states.push_back(s);}
auto run=[&](S&s){std::vector<uint64_t>reset(s.m*s.size*s.tasks+2,SENT);ck(cudaMemcpy(s.b,reset.data(),reset.size()*8,cudaMemcpyHostToDevice));ck(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int task=0;task<s.tasks;task++)coding_func_array[(s.m-1)*5+s.w-4](s.k,0,(char*)(s.a+1+task*s.k*s.size),(char*)(s.b+1+task*s.m*s.size),s.bm+1,128,s.blocks,s.size);ck(cudaGetLastError());ck(cudaDeviceSynchronize());return std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();};for(auto&s:states)run(s);for(int trial=1;trial<=5;trial++){auto out=fixture;size_t oi=0;double elapsed=0;bool ok=true;for(auto&s:states){elapsed+=run(s);std::vector<uint64_t>got(s.m*s.size*s.tasks+2),in(s.ah.size());std::vector<uint32_t>bm(s.bh.size());ck(cudaMemcpy(got.data(),s.b,got.size()*8,cudaMemcpyDeviceToHost));ck(cudaMemcpy(in.data(),s.a,in.size()*8,cudaMemcpyDeviceToHost));ck(cudaMemcpy(bm.data(),s.bm,bm.size()*4,cudaMemcpyDeviceToHost));ok&=in==s.ah&&bm==s.bh&&got.front()==SENT&&got.back()==SENT;for(size_t i=1;i+1<got.size();i++)ok&=got[i]==oracle[oi++];out.insert(out.end(),got.begin()+1,got.end()-1);out.insert(out.end(),{in.front(),in.back(),got.front(),got.back()});}std::string path="trial_"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)out.data(),out.size()*8);f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":0,\"timing_region\":\"sum100_preallocated_CauchyRS_kernel_pipelines_complete\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",out.size(),path.c_str(),out.size());if(!ok)return 3;}for(auto&s:states){ck(cudaFree(s.a));ck(cudaFree(s.b));ck(cudaFree(s.bm));}}
